import fs from 'node:fs/promises';import path from 'node:path';import http from 'node:http';import assert from 'node:assert/strict';
import {chromium} from '../../.local/browser-test/node_modules/playwright-core/index.mjs';
const root=path.resolve('.local/browser-gate-20260920/candidate'),out=path.resolve('evidence/browser-gate-20260920');
const server=http.createServer(async(req,res)=>{try{const u=new URL(req.url,'http://local');if(u.pathname==='/runtime-config.js'){res.setHeader('Content-Type','text/javascript');res.end('globalThis.__BNBU_PUBLIC_CONFIG__={appEnv:"test"};');return;}if(u.pathname.startsWith('/api/')){res.setHeader('Content-Type','application/json');res.statusCode=503;res.end(JSON.stringify({code:'SYSTEM_SERVICE_UNAVAILABLE'}));return;}const file=path.resolve(root,'.'+u.pathname+(u.pathname.endsWith('/')?'index.html':''));assert.ok(file.startsWith(root+path.sep));res.setHeader('Content-Type',file.endsWith('.js')?'text/javascript':file.endsWith('.css')?'text/css':file.endsWith('.html')?'text/html':file.endsWith('.svg')?'image/svg+xml':'application/octet-stream');res.end(await fs.readFile(file));}catch{res.statusCode=404;res.end();}});await new Promise(r=>server.listen(0,'127.0.0.1',r));
const browser=await chromium.launch({executablePath:'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',headless:true});
const android='Mozilla/5.0 (Linux; Android 15; Pixel 9) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Mobile Safari/537.36';const ios='Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko)';
const cases=[['wechat',android+' MicroMessenger/8.0',false],['safari',ios+' Version/18.0 Mobile/15E148 Safari/604.1',true],['samsung',android+' SamsungBrowser/28.0',false],['firefox',ios+' FxiOS/130.0 Mobile/15E148 Safari/604.1',true],['chrome-android',android,true],['edge-android',android+' EdgA/140.0',true],['chrome-ios',ios+' CriOS/140.0 Mobile/15E148 Safari/604.1',true],['edge-ios',ios+' EdgiOS/140.0 Mobile/15E148 Safari/604.1',true]];
const results=[];
try{for(const [name,userAgent,allowed] of cases){const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,userAgent});await context.addInitScript(()=>{Object.defineProperty(navigator,'userAgentData',{value:undefined});Object.defineProperty(navigator,'clipboard',{value:{writeText:async value=>{window.copiedLink=value;}}});});const page=await context.newPage(),api=[],errors=[];page.on('request',r=>{if(r.url().includes('/api/'))api.push(r.url());});page.on('pageerror',e=>errors.push(e.message));const url='http://127.0.0.1:'+server.address().port+'/student/?invite=synthetic-test#join';await page.goto(url);await page.waitForTimeout(1200);
if(!allowed){assert.equal(await page.locator('[data-browser-blocked]').count(),1,name);assert.equal(api.length,0,name);assert.equal(await page.locator('[data-action="login.sendCode"]').count(),0);await page.locator('[data-copy-browser-link]').click();assert.equal(await page.evaluate(()=>window.copiedLink),url);assert.equal(await page.getByRole('link',{name:'下载 Microsoft Edge',exact:true}).getAttribute('href'),'https://www.microsoft.com/edge/download');if(name==='wechat')await page.screenshot({path:out+'/wechat-blocked.png',fullPage:true});await page.evaluate(async()=>{const {app}=await import('/student/js/app.js');app.state.authenticated=true;app.render();});assert.equal(await page.locator('[data-browser-blocked]').count(),1);assert.equal(api.length,0);
}else{assert.equal(await page.locator('[data-browser-blocked]').count(),0,name);assert.ok(api.length>0,name+' boots API');}
assert.deepEqual(errors,[],name);results.push({name,allowed,apiRequests:api.length,pageErrors:errors});await context.close();}
await fs.writeFile(out+'/browser.json',JSON.stringify({result:'PASS',scenarios:results,scope:'Automated browser identity simulations, not physical phone acceptance'},null,2));console.log(JSON.stringify(results));}finally{await browser.close();await new Promise(r=>server.close(r));}
